import type { HttpInit, HttpResponse } from 'claude-code'

import { CHUNK, MAX_STEPS } from './log'
import type { LogMsg } from './log'
import type { BotLevel, BotRow, ClientMsg, Incoming, Leaderboard, Online, Opponent } from '../types'

export type Fetch = (url: string, init?: HttpInit) => Promise<HttpResponse>

export type GiveUp = (signal: AbortSignal) => Promise<void>

// The returned fetch rejects once giveUp resolves, and cancels giveUp once the request settles.
export const withGiveUp =
  (fetch: Fetch, giveUp: GiveUp): Fetch =>
  async (url, init) => {
    const stop = new AbortController()
    const timedOut = giveUp(stop.signal).then(
      () => Promise.reject(new Error('timed out')),
      () => new Promise<never>(() => undefined),
    )
    try {
      return await Promise.race([fetch(url, init), timedOut])
    } finally {
      stop.abort()
    }
  }

export type Reply<T> = { ok: true; data: T } | { ok: false; status: number; error: string }

// The server's cap on garbage in one log, so also the most a room can deliver.
export const MAX_INCOMING = 10_000

export const PROTOCOL_VERSION = 3
const KEY = /^[A-Za-z0-9_-]{1,64}$/
// 200,000 input pairs and 10,000 garbage pairs, the server's caps.
const MAX_STREAM = 420_000

export function serverUrlOk(u: string): boolean {
  if (u.length > 200) return false
  try {
    const url = new URL(u)
    return url.protocol === 'https:' || (url.protocol === 'http:' && (url.hostname === 'localhost' || url.hostname === '127.0.0.1'))
  } catch {
    return false
  }
}

export function buildRequest(
  base: string,
  method: 'GET' | 'POST' | 'DELETE',
  path: string,
  token: string | null,
  body?: unknown,
): { url: string; init: HttpInit } {
  const headers: Record<string, string> = {
    ...(token === null ? {} : { Authorization: `Bearer ${token}` }),
    Accept: 'application/json',
    'X-Protocol-Version': String(PROTOCOL_VERSION),
  }
  if (body !== undefined) headers['Content-Type'] = 'application/json'

  return {
    url: base.replace(/\/+$/, '') + path,
    init: { method, headers, ...(body === undefined ? {} : { body: JSON.stringify(body) }) },
  }
}

export async function call(
  fetch: Fetch,
  base: string,
  method: 'GET' | 'POST' | 'DELETE',
  path: string,
  token: string | null,
  body?: unknown,
  giveUp: GiveUp = () => new Promise(() => undefined),
): Promise<Reply<unknown>> {
  const { url, init } = buildRequest(base, method, path, token, body)
  try {
    const res = await withGiveUp(fetch, giveUp)(url, init)
    let data: unknown = null
    try {
      data = JSON.parse(res.text)
    } catch {
      // a non-JSON body (a proxy error page) is handled below by status
    }
    if (res.ok) return { ok: true, data }
    const error = (data as { error?: unknown } | null)?.error

    return { ok: false, status: res.status, error: typeof error === 'string' ? cleanText(error) : `HTTP ${res.status}` }
  } catch {
    return { ok: false, status: 0, error: 'unreachable' }
  }
}

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null
const LOGIN = /^[A-Za-z0-9-]{1,39}$/
const SNAPSHOT = /^[.IOTSZJLG]{0,400}$/
export const login = (v: unknown): string | null => (typeof v === 'string' && LOGIN.test(v) ? v : null)
const num = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) ? v : 0)
const count = (v: unknown): v is number => typeof v === 'number' && Number.isInteger(v) && v >= 0
export const cleanText = (s: string) => s.replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2066-\u2069]/g, '').slice(0, 120)

const isLevel = (v: unknown): v is BotLevel => v === 'easy' || v === 'medium' || v === 'hard'

const botRows = (v: unknown): BotRow[] =>
  (Array.isArray(v) ? v : [])
    .filter(isRecord)
    .filter(r => login(r.login) && count(r.ms) && count(r.at))
    .map(r => ({ login: r.login as string, ms: r.ms as number, at: r.at as number }))
    .slice(0, 5)

// A server older than 1.1.0 sends no `bot`; its boards then read as empty.
export function parseLeaderboard(data: unknown): Leaderboard | null {
  if (!isRecord(data) || !Array.isArray(data.marathon) || !Array.isArray(data.wins)) return null
  const marathon = data.marathon
    .filter(isRecord)
    .filter(r => login(r.login) && count(r.score) && count(r.lines) && count(r.level) && count(r.at))
    .map(r => ({ login: r.login as string, score: r.score as number, lines: r.lines as number, level: r.level as number, at: r.at as number }))
  const wins = data.wins
    .filter(isRecord)
    .filter(r => login(r.login) && count(r.wins))
    .map(r => ({ login: r.login as string, wins: r.wins as number }))
  const bot = isRecord(data.bot) ? data.bot : {}

  return { marathon: marathon.slice(0, 5), wins: wins.slice(0, 5), bot: { easy: botRows(bot.easy), medium: botRows(bot.medium), hard: botRows(bot.hard) } }
}

export type QueueReply = (
  | { status: 'waiting' }
  | { status: 'matched'; roomId: string; seed: number; opponent: string }
) & { online: Online | null }

const MAX_ONLINE = 100_000

// Servers before 1.3.0 send no counts.
function parseOnline(v: unknown): Online | null {
  if (!isRecord(v) || !count(v.playing) || !count(v.looking)) return null

  return { playing: Math.min(v.playing, MAX_ONLINE), looking: Math.min(v.looking, MAX_ONLINE) }
}

export function parseQueue(data: unknown): QueueReply | null {
  if (!isRecord(data)) return null
  const online = parseOnline(data.online)
  if (data.status === 'waiting') return { status: 'waiting', online }
  if (data.status === 'matched' && typeof data.roomId === 'string' && KEY.test(data.roomId) && count(data.seed)) {
    const opp = isRecord(data.opponent) ? login(data.opponent.login) : null
    if (opp) return { status: 'matched', roomId: data.roomId, seed: data.seed, opponent: opp, online }
  }

  return null
}

export function parseMarathonStart(data: unknown): { gameId: string; seed: number } | null {
  if (!isRecord(data) || typeof data.gameId !== 'string' || !KEY.test(data.gameId)) return null
  const { seed } = data

  return count(seed) && seed < 2 ** 32 ? { gameId: data.gameId, seed } : null
}

export type SyncReply = { opponent: Opponent | null; incoming: Incoming[]; ended: boolean; winner: string | null }

export function parseSync(data: unknown): SyncReply | null {
  if (!isRecord(data)) return null
  const o = isRecord(data.opponent) ? data.opponent : null
  const snapshot = typeof o?.snapshot === 'string' ? o.snapshot : ''
  const name = login(o?.login)
  const opp = o && name && SNAPSHOT.test(snapshot) ? { login: name, snapshot, isOver: o.isOver === true } : null
  const incoming = Array.isArray(data.incoming)
    ? data.incoming
        .slice(0, MAX_INCOMING)
        .filter(isRecord)
        .filter(a => count(a.id) && (a.id as number) >= 1 && Number.isInteger(a.lines) && (a.lines as number) >= 1 && (a.lines as number) <= 40)
        .map(a => ({ id: a.id as number, lines: a.lines as number }))
    : []
  const ended = isRecord(data.result)
  const winner = ended ? login((data.result as Record<string, unknown>).winner) : null

  return { opponent: opp, incoming, ended, winner }
}

// The server may redeliver a batch when a poll is retried; the id is the identity, so keep the first copy of each.
// Stops at MAX_INCOMING: past that the log could not hold them anyway.
export function mergeIncoming(have: readonly Incoming[], got: readonly Incoming[]): Incoming[] {
  const seen = new Set(have.map(a => a.id))
  const fresh = got.filter(a => !seen.has(a.id) && seen.add(a.id))

  return [...have, ...fresh.slice(0, MAX_INCOMING - have.length)]
}

// Attacks go out in a payload with a seq. A failed send is retried with the same seq and the
// same attacks, which the server treats as idempotent; attacks made meanwhile wait in `queued`.
export type Outbox = {
  seq: number
  inflight: { seq: number; attacks: number[] } | null
  queued: number[]
}

export const emptyOutbox = (): Outbox => ({ seq: 0, inflight: null, queued: [] })

export function nextPayload(box: Outbox): { seq: number; attacks: number[] } {
  if (box.inflight) return box.inflight
  const attacks = box.queued.splice(0, 20)
  box.seq += 1
  box.inflight = { seq: box.seq, attacks }

  return box.inflight
}

export function queueAttacks(box: Outbox, lines: readonly number[]): void {
  for (const n of lines) if (Number.isInteger(n) && n >= 1) box.queued.push(Math.min(40, n))
}

// A Client posts plain data the hooks side must treat as input, not fact.
export function parseClientMsg(data: unknown): ClientMsg | null {
  if (!isRecord(data)) return null
  if (data.type === 'menu') {
    const c = data.choice
    if (c === 'battle') return typeof data.server === 'string' && serverUrlOk(data.server) ? { type: 'menu', choice: c, server: data.server } : null
    if (c === 'bot') return isLevel(data.level) && count(data.nonce) ? { type: 'menu', choice: c, level: data.level, nonce: data.nonce } : null
    if (c === 'marathon') return count(data.nonce) ? { type: 'menu', choice: c, nonce: data.nonce } : null

    return c === 'leaderboard' || c === 'back' ? { type: 'menu', choice: c } : null
  }
  if (data.type === 'log') return parseLogMsg(data)
  if (data.type === 'sync') {
    const { snapshot, isOver, attacks } = data
    if (typeof snapshot !== 'string' || snapshot.length > 400 || typeof isOver !== 'boolean') return null
    if (!Array.isArray(attacks) || !attacks.every(a => Number.isInteger(a))) return null

    return { type: 'sync', seq: num(data.seq), attacks: attacks as number[], snapshot, isOver }
  }

  return null
}

function parseLogMsg(d: Record<string, unknown>): LogMsg | null {
  const { kind, key, steps, inputsLen, total, at, values } = d
  if (kind !== 'marathon' && kind !== 'battle' && kind !== 'bot') return null
  if (typeof key !== 'string' || !KEY.test(key)) return null
  if (!count(steps) || steps < 1 || steps > MAX_STEPS) return null
  if (!count(total) || total > MAX_STREAM || total % 2 !== 0) return null
  if (!count(inputsLen) || inputsLen % 2 !== 0 || inputsLen > total) return null
  if (!count(at) || at > total) return null
  if (!Array.isArray(values) || values.length > CHUNK || at + values.length > total || !values.every(count)) return null

  return { type: 'log', kind, key, steps, inputsLen, total, at, values: values as number[] }
}

