const W = 10
const H = 40
const VISIBLE_TOP = 20
const LOCK_MS = 500
const MAX_RESETS = 15
const MAX_LEVEL = 15
const KINDS: Kind[] = ['I', 'O', 'T', 'S', 'Z', 'J', 'L']

type Pt = readonly [number, number]
const BASE: Record<Kind, Pt[]> = {
