    let points = Math.floor(LINE_SCORE[kind] * level * (b2bApplied ? 1.5 : 1))
    let perfect = false
    if (n > 0) {
      g.combo++
      points += 50 * g.combo * level
      perfect = g.board.every(r => r.every(c => c == null))
      if (perfect) points += (n === 4 && b2bApplied ? PC_B2B_QUAD : PC_SCORE[n]!) * level
      g.b2b = difficult
