    g.lines += n
    const lv = Math.min(MAX_LEVEL, 1 + Math.floor(g.lines / 10))
    if (lv > g.level) {
      g.level = lv
      events.push({ type: 'levelUp', level: lv })
    }
  } else if (g.pendingGarbage.length > 0) {
